export const decodeAudioData = async (
  base64Data: string, 
  ctx: AudioContext
): Promise<AudioBuffer> => {
  const binaryString = atob(base64Data);
  const len = binaryString.length;
  const bytes = new Uint8Array(len);
  for (let i = 0; i < len; i++) {
    bytes[i] = binaryString.charCodeAt(i);
  }

  const arrayBuffer = bytes.buffer;
  const dataInt16 = new Int16Array(arrayBuffer);
  const sampleRate = 24000;
  const numChannels = 1;
  const frameCount = dataInt16.length / numChannels;
  const audioBuffer = ctx.createBuffer(numChannels, frameCount, sampleRate);

  for (let channel = 0; channel < numChannels; channel++) {
    const channelData = audioBuffer.getChannelData(channel);
    for (let i = 0; i < frameCount; i++) {
      channelData[i] = dataInt16[i * numChannels + channel] / 32768.0;
    }
  }
  return audioBuffer;
};

async function retry<T>(fn: () => Promise<T>, retries = 3, delay = 2000): Promise<T> {
  try {
    return await fn();
  } catch (error: any) {
    if (retries > 0) {
      const isRetryable = error.message?.includes('500') || error.message?.includes('Rpc failed') || error.message?.includes('fetch');
      if (isRetryable) {
        await new Promise(resolve => setTimeout(resolve, delay));
        return retry(fn, retries - 1, delay * 1.5);
      }
    }
    throw error;
  }
}

export const generateAnalysis = async (
  input: UserInput, 
  matrix: MatrixNumbers
): Promise<AnalysisResult> => {
  const currentYear = new Date().getFullYear();
  const prompt = `
    You are an expert Numerologist "Chubuk". Create a "Full Matrix Analysis" for:
    User: ${input.name} (${input.gender}), Born: ${input.birthDate}
    Matrix: Personality ${matrix.day}, Talent ${matrix.month}, Money ${matrix.year}, Karma ${matrix.bottom}, Soul ${matrix.center}, Destiny ${matrix.destiny}.
    Return JSON (Russian). Style: Mystical, Deep.
  `;

  return retry(async () => {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            introduction: { type: Type.STRING },
            sections: {
              type: Type.ARRAY,
              items: {
                type: Type.OBJECT,
                properties: {
                  title: { type: Type.STRING },
                  content: { type: Type.STRING }
                },
                required: ["title", "content"]
              }
            },
            forecast: { type: Type.STRING }
          },
          required: ["introduction", "sections", "forecast"]
        }
      }
    });
    return JSON.parse(response.text) as AnalysisResult;
  });
};

export const generateTarotReading = async (
  cards: TarotCard[],
  context?: { userInput: UserInput | null, matrix: MatrixNumbers | null }
): Promise<TarotReading> => {
  const cardsStr = cards.map((c, i) => `Position ${i+1}: ${c.name}`).join(", ");
  let contextPrompt = "";
  if (context?.matrix) {
    contextPrompt = `Connect this interpretation to the user's Destiny Matrix Energy ${context.matrix.destiny} and Soul Center ${context.matrix.center}.`;
  }

  const prompt = `
    You are "Chubuk", a master of Tarot and Numerology. Interpret this Tarot spread: ${cardsStr}.
    User: ${context?.userInput?.name || "Seeker"}.
    ${contextPrompt}
    Return JSON in Russian. 
    Fields: interpretation (deep symbolic meaning), advice (practical mystical guidance).
  `;

  return retry(async () => {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            interpretation: { type: Type.STRING },
            advice: { type: Type.STRING }
          },
          required: ["interpretation", "advice"]
        }
      }
    });
    return {
      cards,
      ...JSON.parse(response.text)
    } as TarotReading;
  });
};

export const getEnergyAnalysis = async (
  position: string,
  value: number,
  gender: 'male' | 'female'
): Promise<EnergyDetails> => {
  const prompt = `Analyze energy ${value} in position "${position}" for ${gender}. Return JSON (Russian).`;
  return retry(async () => {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash',
      contents: prompt,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            general: { type: Type.STRING },
            positive: { type: Type.STRING },
            negative: { type: Type.STRING },
            advice: { type: Type.STRING }
          },
          required: ["general", "positive", "negative", "advice"]
        }
      }
    });
    return JSON.parse(response.text) as EnergyDetails;
  });
};

export const getSpeech = async (text: string, voiceName: string = 'Kore'): Promise<string> => {
  const safeText = text.length > 5000 ? text.substring(0, 5000) : text;
  const prompt = `Read in Russian, mystical tone: "${safeText}"`;
  return retry(async () => {
    const response = await ai.models.generateContent({
      model: "gemini-2.5-flash-preview-tts",
      contents: [{ parts: [{ text: prompt }] }],
      config: {
        responseModalities: [Modality.AUDIO],
        speechConfig: {
          voiceConfig: {
            prebuiltVoiceConfig: { voiceName },
          },
        },
      },
    });
    const base64Audio = response.candidates?.[0]?.content?.parts?.[0]?.inlineData?.data;
    if (!base64Audio) throw new Error("No audio data");
    return base64Audio;
  });
};

export const generateMysticalBackground = async (inputName: string): Promise<string | null> => {
  const prompt = `Abstract mystical background wallpaper, sacred geometry, gold dust, deep purple, metaphysical aesthetic for "${inputName}"`;
  try {
    const response = await ai.models.generateContent({
      model: 'gemini-2.5-flash-image',
      contents: { parts: [{ text: prompt }] },
    });
    for (const part of response.candidates?.[0]?.content?.parts || []) {
      if (part.inlineData) return `data:image/png;base64,${part.inlineData.data}`;
    }
    return null;
  } catch { return null; }
};

export const chatWithChubuk = async (
  message: string, 
  history: { role: 'user' | 'model', text: string }[],
  context?: { userInput: UserInput | null, matrix: MatrixNumbers | null }
): Promise<string> => {
  let contextPrompt = context?.matrix ? `Matrix Destiny: ${context.matrix.destiny}` : "";
  const systemInstruction = `You are "Chubuk", a mystical Numerologist. Tone: Deep, warm. Russian language. ${contextPrompt}`;
  const chatHistoryStr = history.map(h => `${h.role === 'user' ? 'User' : 'Chubuk'}: ${h.text}`).join('\n');
  const fullPrompt = `${systemInstruction}\n\nHistory:\n${chatHistoryStr}\n\nUser: ${message}\nChubuk:`;

  return retry(async () => {
    const response = await ai.models.generateContent({
      model: 'gemini-3-pro-preview',
      contents: fullPrompt,
    });
    return response.text || "Error";
  });
};

import React, { useState } from 'react';
import { TarotCard, TarotReading, UserInput, MatrixNumbers } from '../types';
import { generateTarotReading, MAJOR_ARCANA } from '../services/geminiService';

interface TarotSectionProps {
  userInput: UserInput | null;
  matrix: MatrixNumbers | null;
}

const TarotSection: React.FC<TarotSectionProps> = ({ userInput, matrix }) => {
  const [reading, setReading] = useState<TarotReading | null>(null);
  const [isLaying, setIsLaying] = useState(false);
  const [selectedSpread, setSelectedSpread] = useState<'day' | 'trinity'>('day');
  const [revealedIndices, setRevealedIndices] = useState<number[]>([]);

  const handleReading = async () => {
    setIsLaying(true);
    setReading(null);
    setRevealedIndices([]);

    // Simulate "shuffling"
    await new Promise(resolve => setTimeout(resolve, 1500));

    const count = selectedSpread === 'day' ? 1 : 3;
    const shuffled = [...MAJOR_ARCANA].sort(() => 0.5 - Math.random());
    const pickedCards: TarotCard[] = shuffled.slice(0, count).map((name, id) => ({ id, name }));

    try {
      const result = await generateTarotReading(pickedCards, { userInput, matrix });
      setReading(result);
    } catch (error) {
      console.error(error);
    } finally {
      setIsLaying(false);
    }
  };

  const toggleReveal = (index: number) => {
    if (!revealedIndices.includes(index)) {
      setRevealedIndices([...revealedIndices, index]);
    }
  };

  return (
    <section className="w-full max-w-5xl mx-auto py-20 px-4">
      <div className="text-center mb-12">
        <h2 className="text-4xl md:text-6xl font-serif text-amber-100 mb-6 drop-shadow-xl">
          Священное <span className="text-transparent bg-clip-text bg-gradient-to-r from-amber-200 via-amber-400 to-amber-600">Таро</span>
        </h2>
        <p className="text-slate-400 max-w-xl mx-auto text-lg font-light">
          Карты Таро — это зеркало вашей души. Выберите расклад и позвольте энергиям арканов дать вам ответ.
        </p>
      </div>

      <div className="flex flex-col items-center gap-12">
        {/* Spread Selector */}
        <div className="flex bg-black/40 p-2 rounded-2xl border border-white/10 no-print">
          <button
            onClick={() => { setSelectedSpread('day'); setReading(null); }}
            className={`px-8 py-3 rounded-xl transition-all font-serif ${selectedSpread === 'day' ? 'bg-amber-500 text-black shadow-lg shadow-amber-500/20' : 'text-slate-400 hover:text-white'}`}
          >
            Карта Дня
          </button>
          <button
            onClick={() => { setSelectedSpread('trinity'); setReading(null); }}
            className={`px-8 py-3 rounded-xl transition-all font-serif ${selectedSpread === 'trinity' ? 'bg-amber-500 text-black shadow-lg shadow-amber-500/20' : 'text-slate-400 hover:text-white'}`}
          >
            Триединство
          </button>
        </div>

        {/* Card Area */}
        <div className="flex flex-wrap justify-center gap-8 min-h-[350px] w-full items-center">
          {isLaying ? (
             <div className="flex flex-col items-center gap-4 animate-pulse">
                <div className="w-20 h-20 border-4 border-amber-500/20 border-t-amber-500 rounded-full animate-spin"></div>
                <p className="text-amber-500 font-serif uppercase tracking-widest text-sm">Перемешивание колоды...</p>
             </div>
          ) : reading ? (
            reading.cards.map((card, idx) => (
              <div 
                key={idx} 
                className="perspective-1000 cursor-pointer"
                onClick={() => toggleReveal(idx)}
              >
                <div className={`relative w-48 h-72 transition-all duration-700 transform-style-3d ${revealedIndices.includes(idx) ? 'rotate-y-180' : ''}`}>
