                  <div className="absolute inset-0 backface-hidden rotate-y-180 bg-gradient-to-br from-[#1a162e] to-black rounded-2xl border-2 border-amber-500/50 flex flex-col items-center justify-center p-4 shadow-2xl overflow-hidden">
                    <div className="absolute inset-0 opacity-10 bg-[radial-gradient(circle_at_center,_var(--tw-gradient-stops))] from-amber-500 via-transparent to-transparent"></div>
                    <div className="w-12 h-12 rounded-full border border-amber-500/30 flex items-center justify-center mb-4 text-amber-500 font-serif text-xl">
                      {idx + 1}
                    </div>
                    <h3 className="text-xl font-serif text-amber-100 text-center drop-shadow-md z-10">{card.name}</h3>
                    <div className="mt-auto text-[10px] text-amber-500/50 uppercase tracking-[0.3em] font-bold">Arcana Major</div>
                  </div>

                  {/* Back (Mystic Pattern) */}
                  <div className="absolute inset-0 backface-hidden bg-[#050a14] rounded-2xl border-2 border-amber-500/20 flex items-center justify-center shadow-lg group">
                    <div className="w-full h-full p-4 flex items-center justify-center">
                       <div className="w-full h-full border border-amber-500/10 rounded-xl flex items-center justify-center relative overflow-hidden">
                          <div className="absolute inset-0 bg-[url('https://www.transparenttextures.com/patterns/sacred-geometry.png')] opacity-20"></div>
                          <div className="w-16 h-16 border-2 border-amber-500/40 rounded-full flex items-center justify-center group-hover:scale-110 transition-transform duration-500">
                             <span className="text-amber-500 text-2xl font-serif">†</span>
                          </div>
                       </div>
                    </div>
                  </div>
                </div>
                {selectedSpread === 'trinity' && (
                  <p className="text-center mt-4 text-[10px] uppercase tracking-widest text-slate-500 font-bold">
                    {idx === 0 ? "Прошлое" : idx === 1 ? "Настоящее" : "Будущее"}
