                </svg>
                <span className="text-xs uppercase tracking-widest font-bold text-slate-500 group-hover:text-amber-400">Разложить Карты</span>
              </div>
            </button>
          )}
        </div>

        {/* Result Interpretation */}
        {reading && revealedIndices.length === reading.cards.length && (
          <div className="w-full card-3d rounded-3xl p-8 md:p-12 animate-fade-in-up">
            <div className="grid md:grid-cols-3 gap-12">
               <div className="md:col-span-2 space-y-6">
                  <h4 className="text-2xl font-serif text-amber-100 flex items-center gap-3">
                    <span className="w-1 h-8 bg-amber-500 rounded-full"></span>
                    Толкование Арканов
                  </h4>
                  <p className="text-slate-300 leading-relaxed text-lg font-light whitespace-pre-wrap">
                    {reading.interpretation}
                  </p>
               </div>
               <div className="bg-amber-500/5 border border-amber-500/20 p-6 rounded-2xl flex flex-col justify-center">
                  <h4 className="text-amber-400 font-serif mb-4 flex items-center gap-2">
