                  <button 
                    onClick={() => { setReading(null); setRevealedIndices([]); }}
                    className="mt-8 text-xs text-amber-500/50 hover:text-amber-500 uppercase tracking-widest font-bold transition-colors text-center border-t border-amber-500/10 pt-4"
