  const [toastMessage, setToastMessage] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'matrix' | 'tarot'>('matrix');

  // Refs
  const calculatorRef = useRef<HTMLDivElement>(null);
  const resultsRef = useRef<HTMLDivElement>(null);
  const tarotRef = useRef<HTMLDivElement>(null);
  const topRef = useRef<HTMLDivElement>(null);
  const bgBlob1Ref = useRef<HTMLDivElement>(null);
  const bgBlob2Ref = useRef<HTMLDivElement>(null);
  const heroTextRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    try {
      const savedInput = localStorage.getItem('chubuk_user_input');
      const savedMatrix = localStorage.getItem('chubuk_matrix_data');
      if (savedInput && savedMatrix) {
        setUserInput(JSON.parse(savedInput));
        setMatrix(JSON.parse(savedMatrix));
      }
    } catch (e) { console.error(e); }
