import React, { useState, useRef, useEffect } from 'react';
import { AnalysisResult } from '../types';
import { getSpeech, decodeAudioData, VOICE_OPTIONS, chatWithChubuk } from '../services/geminiService';

interface AnalysisResultsProps {
  analysis: AnalysisResult;
  userInput: any;
  matrix: any;
}

const AnalysisResults: React.FC<AnalysisResultsProps> = ({ analysis, userInput, matrix }) => {
  const [openIndex, setOpenIndex] = useState<number | null>(0);
  const [selectedVoice, setSelectedVoice] = useState(VOICE_OPTIONS[0].name);
  const [question, setQuestion] = useState('');
  const [answer, setAnswer] = useState<string | null>(null);
  const [isAsking, setIsAsking] = useState(false);

  // Audio State
  const [playingSection, setPlayingSection] = useState<number | string | null>(null);
  const [audioLoading, setAudioLoading] = useState<number | string | null>(null);
  const audioCtxRef = useRef<AudioContext | null>(null);
  const sourceRef = useRef<AudioBufferSourceNode | null>(null);

  useEffect(() => {
    return () => stopAudio();
  }, []);

  const toggleSection = (index: number) => {
    setOpenIndex(openIndex === index ? null : index);
  };

  const handleAskQuestion = async () => {
    if (!question.trim()) return;
    setIsAsking(true);
    setAnswer(null);
    stopAudio();

    try {
      const response = await chatWithChubuk(question, [], { userInput, matrix });
      setAnswer(response);
      // Automatically read the answer
      playSectionAudio(response, 'answer', { stopPropagation: () => {} } as any);
    } catch (e) {
      console.error(e);
      setAnswer("Энергии сегодня туманны. Попробуйте сформулировать иначе.");
    } finally {
      setIsAsking(false);
    }
  };

  const playSectionAudio = async (text: string, id: number | string, event: React.MouseEvent) => {
    event.stopPropagation();

    if (playingSection === id) {
      stopAudio();
      return;
    }

    stopAudio();
    setAudioLoading(id);

    try {
      if (!audioCtxRef.current) {
        audioCtxRef.current = new (window.AudioContext || (window as any).webkitAudioContext)({ sampleRate: 24000 });
      }

      const ctx = audioCtxRef.current;
      if (ctx.state === 'suspended') {
        await ctx.resume();
      }

      const base64Audio = await getSpeech(text, selectedVoice);
      const buffer = await decodeAudioData(base64Audio, ctx);

      const source = ctx.createBufferSource();
      source.buffer = buffer;
      source.connect(ctx.destination);
      source.onended = () => setPlayingSection(null);
      source.start();

      sourceRef.current = source;
      setPlayingSection(id);

    } catch (e) {
      console.error("Audio playback error", e);
    } finally {
      setAudioLoading(null);
    }
  };

  const stopAudio = () => {
    if (sourceRef.current) {
      try {
        sourceRef.current.stop();
        sourceRef.current.disconnect();
      } catch (e) { /* ignore */ }
      sourceRef.current = null;
    }
    setPlayingSection(null);
  };

  const getIcon = (index: number) => {
    switch (index) {
      case 0: return <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M16 7a4 4 0 11-8 0 4 4 0 018 0zM12 14a7 7 0 00-7 7h14a7 7 0 00-7-7z" />;
      case 1: return <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 8c-1.657 0-3 .895-3 2s1.343 2 3 2 3 .895 3 2-1.343 2-3 2m0-8c1.11 0 2.08.402 2.599 1M12 8V7m0 1v8m0 0v1m0-1c-1.11 0-2.08-.402-2.599-1M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />;
      default: return <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M13 16h-1v-4h-1m1-4h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />;
    }
  };

  return (
    <div className="w-full max-w-4xl mx-auto space-y-8 pb-10">

      <div className="card-3d rounded-3xl p-8 relative overflow-hidden group hover:shadow-[0_20px_40px_rgba(251,191,36,0.15)] transition-all duration-500 animate-fade-in-up">
        <div className="absolute top-0 right-0 w-64 h-64 bg-amber-500/10 rounded-full blur-[80px] -translate-y-1/2 translate-x-1/2 group-hover:bg-amber-500/20 transition-all duration-700"></div>

        <div className="absolute top-6 right-6 z-20 no-print">
          <select
            value={selectedVoice}
            onChange={(e) => { stopAudio(); setSelectedVoice(e.target.value); }}
            className="appearance-none bg-black/40 border border-amber-500/30 rounded-lg py-1 pl-3 pr-8 text-xs text-amber-200 focus:outline-none focus:border-amber-500 cursor-pointer hover:bg-black/60 transition-colors"
          >
            {VOICE_OPTIONS.map(v => (
              <option key={v.name} value={v.name}>{v.label}</option>
            ))}
          </select>
        </div>

        <h3 className="text-3xl font-serif text-amber-100 mb-6 relative z-10 flex items-center gap-4">
          <span className="flex items-center justify-center w-12 h-12 rounded-full bg-amber-500/20 text-amber-500 border border-amber-500/30">
             <span className="font-serif font-bold text-xl">C</span>
          </span>
          <span className="text-glow">Матрица Души</span>
        </h3>
        <div className="prose prose-invert prose-lg max-w-none relative z-10">
          <p className="text-slate-300 font-light leading-relaxed italic pl-6 border-l-2 border-amber-500/30">
            {analysis.introduction}
          </p>
        </div>
      </div>

      <div className="space-y-6">
        {analysis.sections.map((section, index) => (
          <div 
            key={index} 
            className={`transition-all duration-500 rounded-2xl overflow-hidden border card-3d-item ${
              openIndex === index 
                ? 'bg-gradient-to-br from-[#1a162e] to-black border-amber-500/50 shadow-[0_10px_30px_rgba(0,0,0,0.5)] transform scale-[1.01]' 
                : 'bg-white/5 border-white/5 hover:border-white/20 hover:bg-white/10'
            }`}
          >
            <button
              onClick={() => toggleSection(index)}
              className="w-full text-left p-6 flex items-center justify-between group"
            >
              <div className="flex items-center gap-5">
                <div className={`w-14 h-14 rounded-2xl flex items-center justify-center shadow-lg transition-all duration-500 transform group-hover:rotate-6 ${
                  openIndex === index ? 'bg-amber-500 text-black rotate-3' : 'bg-[#0f1219] text-amber-500 border border-amber-500/20'
                }`}>
                  <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    {getIcon(index)}
                  </svg>
                </div>
                <h4 className={`font-serif text-xl font-bold tracking-wide transition-colors ${openIndex === index ? 'text-amber-100' : 'text-slate-300 group-hover:text-white'}`}>
                  {section.title}
                </h4>
              </div>

              <div className="flex items-center gap-4">
                <div 
                   onClick={(e) => playSectionAudio(section.content, index, e)}
                   className={`w-12 h-12 rounded-full flex items-center justify-center transition-all duration-300 z-20 hover:scale-110 shadow-lg ${
                     playingSection === index ? 'bg-green-500 text-white animate-pulse' : 'bg-slate-800 text-slate-400 hover:bg-amber-500 hover:text-black'
                   }`}
                >
                  {audioLoading === index ? (
                     <svg className="animate-spin w-5 h-5" viewBox="0 0 24 24"><circle className="opacity-25" cx="12" cy="12" r="10" stroke="currentColor" strokeWidth="4" fill="none"/><path className="opacity-75" fill="currentColor" d="M4 12a8 8 0 018-8V0C5.373 0 0 5.373 0 12h4zm2 5.291A7.962 7.962 0 014 12H0c0 3.042 1.135 5.824 3 7.938l3-2.647z"/></svg>
                  ) : playingSection === index ? (
                     <div className="flex gap-1 h-3 items-end"><div className="w-1 bg-white h-full animate-bounce"></div><div className="w-1 bg-white h-2/3 animate-bounce"></div></div>
                  ) : (
                     <svg className="w-6 h-6 translate-x-0.5" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14.752 11.168l-3.197-2.132A1 1 0 0010 9.87v4.263a1 1 0 001.555.832l3.197-2.132a1 1 0 000-1.664z" /></svg>
                  )}
                </div>
              </div>
            </button>

            <div className={`overflow-hidden transition-all duration-700 ${openIndex === index ? 'max-h-[2000px] opacity-100' : 'max-h-0 opacity-0'}`}>
              <div className="p-8 pt-2 border-t border-white/5 bg-black/20">
                <p className="text-slate-300 leading-8 font-light text-lg tracking-wide whitespace-pre-wrap">
                  {section.content}
                </p>
              </div>
            </div>
          </div>
        ))}
      </div>

      {/* NEW: Ask specific question about Matrix */}
      <div className="card-3d rounded-3xl p-8 border-amber-500/30 bg-black/40 shadow-inner no-print">
         <h4 className="text-2xl font-serif text-amber-100 mb-4 flex items-center gap-3">
            <svg className="w-6 h-6 text-amber-500" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M8.228 9c.549-1.165 2.03-2 3.772-2 2.21 0 4 1.343 4 3 0 1.4-1.278 2.575-3.006 2.907-.542.104-.994.54-.994 1.093m0 3h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" /></svg>
            Задать вопрос Судьбе
         </h4>
         <p className="text-slate-400 text-sm mb-6 font-light">Спросите Chubuk о конкретной сфере жизни в контексте вашей матрицы.</p>

         <div className="flex gap-4">
            <input 
              type="text" 
              value={question}
              onChange={(e) => setQuestion(e.target.value)}
              placeholder="Например: Какое предназначение мне открыть в этом году?"
              className="flex-1 input-3d rounded-xl px-5 py-3 text-amber-100 outline-none focus:border-amber-500 transition-colors"
            />
            <button 
              onClick={handleAskQuestion}
              disabled={isAsking || !question.trim()}
              className="px-6 py-3 btn-3d rounded-xl font-bold uppercase text-xs tracking-widest disabled:opacity-50"
            >
              {isAsking ? '...' : 'Спросить'}
            </button>
         </div>

         {answer && (
           <div className="mt-8 p-6 bg-white/5 border border-amber-500/20 rounded-2xl animate-fade-in-up">
              <div className="flex items-center justify-between mb-4">
                <span className="text-xs uppercase text-amber-500 font-bold tracking-widest">Ответ Оракула:</span>
                <button
                   onClick={(e) => playSectionAudio(answer, 'answer', e)}
                   className={`w-8 h-8 rounded-full flex items-center justify-center transition-all ${
                     playingSection === 'answer' ? 'bg-amber-500 text-black' : 'text-amber-500 border border-amber-500/30'
                   }`}
                >
                   {playingSection === 'answer' ? (
                     <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 9v6m4-6v6" /></svg>
                   ) : (
                     <svg className="w-4 h-4" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M14.752 11.168l-3.197-2.132A1 1 0 0010 9.87v4.263a1 1 0 001.555.832l3.197-2.132z" /></svg>
                   )}
                </button>
              </div>
              <p className="text-slate-200 italic leading-relaxed">{answer}</p>
           </div>
         )}
      </div>
    </div>
  );
};

