import React, { useState, useRef, useEffect } from 'react';
import InputForm from './components/InputForm';
import MatrixVisual from './components/MatrixVisual';
import OrderSection from './components/OrderSection';
import AnalysisResults from './components/AnalysisResults';
import NumerologistChat from './components/NumerologistChat';
import TarotSection from './components/TarotSection';
import { calculateMatrix } from './services/numerologyUtils';
import { generateAnalysis, generateMysticalBackground } from './services/geminiService';
import { UserInput, MatrixNumbers, AnalysisResult } from './types';

const App: React.FC = () => {
  const [matrix, setMatrix] = useState<MatrixNumbers | null>(null);
  const [analysis, setAnalysis] = useState<AnalysisResult | null>(null);
  const [userInput, setUserInput] = useState<UserInput | null>(null);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [bgImage, setBgImage] = useState<string | null>(null);
  const [toastMessage, setToastMessage] = useState<string | null>(null);
  const [activeTab, setActiveTab] = useState<'matrix' | 'tarot'>('matrix');

  const calculatorRef = useRef<HTMLDivElement>(null);
  const resultsRef = useRef<HTMLDivElement>(null);
  const tarotRef = useRef<HTMLDivElement>(null);
  const topRef = useRef<HTMLDivElement>(null);
  const bgBlob1Ref = useRef<HTMLDivElement>(null);
  const bgBlob2Ref = useRef<HTMLDivElement>(null);
  const heroTextRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    try {
      const savedInput = localStorage.getItem('chubuk_user_input');
      const savedMatrix = localStorage.getItem('chubuk_matrix_data');
      if (savedInput && savedMatrix) {
        setUserInput(JSON.parse(savedInput));
        setMatrix(JSON.parse(savedMatrix));
      }
    } catch (e) { console.error(e); }
  }, []);

  useEffect(() => {
    const handleScroll = () => {
      const y = window.scrollY;
      if (bgBlob1Ref.current) bgBlob1Ref.current.style.transform = `translate3d(0, ${y * 0.2}px, 0)`;
      if (bgBlob2Ref.current) bgBlob2Ref.current.style.transform = `translate3d(0, ${y * -0.15}px, 0)`;
      if (heroTextRef.current) {
        heroTextRef.current.style.transform = `translate3d(0, ${y * 0.4}px, 0)`;
        heroTextRef.current.style.opacity = `${Math.max(0, 1 - y / 600)}`;
      }
    };
    window.addEventListener('scroll', handleScroll);
    return () => window.removeEventListener('scroll', handleScroll);
  }, []);

  const showToast = (message: string) => {
    setToastMessage(message);
    setTimeout(() => setToastMessage(null), 3000);
  };

  const handleCalculate = async (input: UserInput) => {
    setLoading(true);
    setError(null);
    setAnalysis(null);
    setMatrix(null);
    setUserInput(input);
    try {
      const calculatedMatrix = calculateMatrix(input.birthDate);
      setMatrix(calculatedMatrix);
      localStorage.setItem('chubuk_user_input', JSON.stringify(input));
      localStorage.setItem('chubuk_matrix_data', JSON.stringify(calculatedMatrix));
      showToast("Энергии рассчитаны");

      generateMysticalBackground(input.name).then(img => {
        if (img) setBgImage(img);
      });

      const aiResult = await generateAnalysis(input, calculatedMatrix);
      setAnalysis(aiResult);
      setTimeout(() => resultsRef.current?.scrollIntoView({ behavior: 'smooth' }), 100);
    } catch (err) {
      setError("Энергии не ответили. Попробуйте снова.");
    } finally {
      setLoading(false);
    }
  };

  return (
    <div ref={topRef} className="min-h-screen font-sans bg-cosmic-gradient text-slate-100 overflow-x-hidden relative">
      <div className={`fixed top-24 right-6 z-[60] bg-green-900/90 text-green-100 px-6 py-3 rounded-xl backdrop-blur-md border border-green-500/30 shadow-2xl transition-all duration-500 ${toastMessage ? 'translate-x-0 opacity-100' : 'translate-x-[200%] opacity-0'}`}>
        <span className="font-medium text-sm">{toastMessage}</span>
      </div>

      <div className="fixed inset-0 pointer-events-none z-0 overflow-hidden no-print">
         {bgImage && (
            <div className="absolute inset-0 z-0 opacity-40 animate-fade-in" style={{ backgroundImage: `url(${bgImage})`, backgroundSize: 'cover', backgroundPosition: 'center' }}></div>
         )}
         <div ref={bgBlob1Ref} className="absolute top-[-20%] left-[-10%] w-[70%] h-[70%] bg-purple-900/10 rounded-full blur-[120px]"></div>
         <div ref={bgBlob2Ref} className="absolute bottom-[-20%] right-[-10%] w-[70%] h-[70%] bg-amber-600/10 rounded-full blur-[120px]"></div>
      </div>

      <NumerologistChat userInput={userInput} matrix={matrix} />

      <header className="sticky top-0 z-50 bg-[#050a14]/80 backdrop-blur-xl border-b border-white/5 no-print">
        <div className="container mx-auto px-4 py-4 flex justify-between items-center">
          <div className="flex items-center gap-3 cursor-pointer" onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}>
            <div className="w-10 h-10 rounded-xl bg-gradient-to-br from-amber-300 via-amber-500 to-amber-700 flex items-center justify-center font-serif text-black font-bold text-xl shadow-lg">C</div>
            <h1 className="text-xl md:text-2xl font-serif tracking-widest">CHUBUK <span className="text-amber-500">MATRIX</span></h1>
          </div>
          <nav className="hidden md:flex gap-8 text-xs font-bold text-slate-400 uppercase tracking-widest">
            <button onClick={() => setActiveTab('matrix')} className={`transition-colors ${activeTab === 'matrix' ? 'text-amber-400' : 'hover:text-amber-400'}`}>Матрица</button>
            <button onClick={() => setActiveTab('tarot')} className={`transition-colors ${activeTab === 'tarot' ? 'text-amber-400' : 'hover:text-amber-400'}`}>Таро</button>
          </nav>
        </div>
      </header>

      <main className="relative z-10 container mx-auto px-4 py-16 md:py-24 flex flex-col items-center">
        {activeTab === 'matrix' ? (
          <>
            <div ref={heroTextRef} className="text-center max-w-4xl mb-16 no-print">
              <div className="inline-block px-4 py-1 rounded-full bg-amber-500/10 border border-amber-500/20 text-amber-500 text-xs font-bold uppercase mb-6 animate-pulse">Портал Самопознания</div>
