            </div>

            {analysis && (
              <div ref={resultsRef} className="w-full animate-fade-in-up">
                <AnalysisResults analysis={analysis} userInput={userInput} matrix={matrix} />
                <OrderSection onDownload={() => window.print()} isVisible={true} />
              </div>
            )}
          </>
        ) : (
          <div ref={tarotRef} className="w-full">
            <TarotSection userInput={userInput} matrix={matrix} />
          </div>
        )}
      </main>

      <footer className="relative z-10 border-t border-white/5 bg-black/60 py-12 no-print text-center">
        <p className="text-amber-500/40 font-serif text-sm">CHUBUK MATRIX SYSTEM</p>
      </footer>
    </div>
  );
};

